mapper.select:
select a.*, b.avatar as avatar, b.nickname as nickName, c.name as departmentName from team_application_record as a inner join cas_user as b on a.user_id = b.id left join team_department as c on a.department_id = c.id and c.delete_time is null
and a.team_id = #{param.searchId}
and a.status = #{param.searchIntStatus}

select count(1)
from team_application_record
where team_id = #{teamId}
and user_id = #{userId}
and status in (0, 1)
